//! Bounded normal CDF: a division-free erf polynomial in the body and one
//! erfcx rational with an exactly split exponent in the tails
//! (`docs/fast_cdf.md`).
//!
//! The coefficients are generated by `generators/fast_cdf_constants.py`
//! (`cdf_tables.rs`); `formal/fast/FastCdf.v` transcribes this operation
//! sequence and proves its bounds.
#![allow(clippy::excessive_precision, clippy::unreadable_literal)]

use crate::normal_distribution::INV_SQRT2_HIGH;
#[cfg(feature = "simd")]
use morphiq_numerics_arch::Simd;

use super::cdf_tables::{BODY, TAIL_D, TAIL_N};

/// `y = RN(|x|/sqrt 2)` at or below this takes the body polynomial.
pub(super) const BODY_LIMIT: f64 = 0.468_75;

#[inline(always)]
fn estrin9(y: f64, y2: f64, y4: f64, y8: f64, c: &[f64; 9]) -> f64 {
    let a0 = c[0] + y * c[1];
    let a1 = c[2] + y * c[3];
    let a2 = c[4] + y * c[5];
    let a3 = c[6] + y * c[7];
    (a0 + y2 * a1) + y4 * (a2 + y2 * a3) + y8 * c[8]
}

#[inline(always)]
fn estrin10(y: f64, y2: f64, y4: f64, y8: f64, c: &[f64; 10]) -> f64 {
    let a0 = c[0] + y * c[1];
    let a1 = c[2] + y * c[3];
    let a2 = c[4] + y * c[5];
    let a3 = c[6] + y * c[7];
    let a4 = c[8] + y * c[9];
    (a0 + y2 * a1) + y4 * (a2 + y2 * a3) + y8 * a4
}

/// `Phi(x)` for `2^-33 <= |x| <= 8`.
#[inline(always)]
pub(super) fn in_domain(x: f64) -> f64 {
    let a = x.abs();
    let y = a * INV_SQRT2_HIGH;
    if y <= BODY_LIMIT {
        let s = y * y;
        let s2 = s * s;
        let s4 = s2 * s2;
        let c = &BODY;
        let p = ((c[0] + s * c[1]) + s2 * (c[2] + s * c[3]))
            + s4 * ((c[4] + s * c[5]) + s2 * (c[6] + s * c[7]))
            + (s4 * s4) * c[8];
        return 0.5 + 0.5 * ((x * INV_SQRT2_HIGH) * p);
    }
    // exp(-a²/2) = exp(p)(1 + e) to first order; the correction joins the
    // rational, off the exponential's dependency chain.
    let (p, e) = crate::eft::two_prod_d(-0.5 * a, a);
    let exponential = crate::exp::bounded::in_domain(p);
    let y2 = y * y;
    let y4 = y2 * y2;
    let y8 = y4 * y4;
    let r = estrin9(y, y2, y4, y8, &TAIL_N) / estrin10(y, y2, y4, y8, &TAIL_D);
    let lower = (0.5 * exponential) * (r + r * e);
    if x < 0.0 { lower } else { 1.0 - lower }
}

#[cfg(feature = "simd")]
#[inline(always)]
fn estrin9_lanes<K: Simd>(k: K, y: K::F, y2: K::F, y4: K::F, y8: K::F, c: &[f64; 9]) -> K::F {
    let t = |i: usize| k.add(k.splat(c[i]), k.mul(y, k.splat(c[i + 1])));
    let (a0, a1, a2, a3) = (t(0), t(2), t(4), t(6));
    k.add(
        k.add(
            k.add(a0, k.mul(y2, a1)),
            k.mul(y4, k.add(a2, k.mul(y2, a3))),
        ),
        k.mul(y8, k.splat(c[8])),
    )
}

#[cfg(feature = "simd")]
#[inline(always)]
fn estrin10_lanes<K: Simd>(k: K, y: K::F, y2: K::F, y4: K::F, y8: K::F, c: &[f64; 10]) -> K::F {
    let t = |i: usize| k.add(k.splat(c[i]), k.mul(y, k.splat(c[i + 1])));
    let (a0, a1, a2, a3, a4) = (t(0), t(2), t(4), t(6), t(8));
    k.add(
        k.add(
            k.add(a0, k.mul(y2, a1)),
            k.mul(y4, k.add(a2, k.mul(y2, a3))),
        ),
        k.mul(y8, a4),
    )
}

/// [`in_domain`] on lanes; `active` marks the lanes inside its domain, and the
/// others evaluate harmless substitutes whose results the caller replaces.
#[cfg(feature = "simd")]
#[inline(always)]
pub(super) fn lanes<K: Simd>(k: K, x: K::F, active: K::M) -> K::F {
    let a = k.abs(x);
    let y = k.mul(a, k.splat(INV_SQRT2_HIGH));
    let body = k.and_m(active, k.le(y, k.splat(BODY_LIMIT)));
    let outer = k.and_m(active, k.not_m(body));
    let mut out = k.splat(0.0);
    if k.mask_bits(body) != 0 {
        let xb = k.select(body, x, k.splat(0.25));
        let yb = k.select(body, y, k.splat(0.25));
        let s = k.mul(yb, yb);
        let s2 = k.mul(s, s);
        let s4 = k.mul(s2, s2);
        let c = &BODY;
        let pair = |i: usize| k.add(k.splat(c[i]), k.mul(s, k.splat(c[i + 1])));
        let p = k.add(
            k.add(
                k.add(pair(0), k.mul(s2, pair(2))),
                k.mul(s4, k.add(pair(4), k.mul(s2, pair(6)))),
            ),
            k.mul(k.mul(s4, s4), k.splat(c[8])),
        );
        let value = k.add(
            k.splat(0.5),
            k.mul(k.splat(0.5), k.mul(k.mul(xb, k.splat(INV_SQRT2_HIGH)), p)),
        );
        out = k.select(body, value, out);
    }
    if k.mask_bits(outer) != 0 {
        let safe = k.select(outer, a, k.splat(1.0));
        let ys = k.select(outer, y, k.splat(1.0));
        let (p, e) = crate::lanes::two_prod(k, k.mul(k.splat(-0.5), safe), safe);
        let exponential = crate::exp::bounded::in_domain_lanes(k, p);
        let y2 = k.mul(ys, ys);
        let y4 = k.mul(y2, y2);
        let y8 = k.mul(y4, y4);
        let r = k.div(
            estrin9_lanes(k, ys, y2, y4, y8, &TAIL_N),
            estrin10_lanes(k, ys, y2, y4, y8, &TAIL_D),
        );
        let lower = k.mul(k.mul(k.splat(0.5), exponential), k.add(r, k.mul(r, e)));
        let value = k.select(k.lt(x, k.splat(0.0)), lower, k.sub(k.splat(1.0), lower));
        out = k.select(outer, value, out);
    }
    out
}
